function timestamp(seconds) {
  const milliseconds = Math.round(seconds * 1000);
  const hours = Math.floor(milliseconds / 3600000);
  const minutes = Math.floor((milliseconds % 3600000) / 60000);
  const wholeSeconds = Math.floor((milliseconds % 60000) / 1000);
  const remainder = milliseconds % 1000;
  return [hours, minutes, wholeSeconds].map((value) => String(value).padStart(2, '0')).join(':')
    + `,${String(remainder).padStart(3, '0')}`;
}

function srtText() {
  return NARRATION_CUES.map(([start, end, text], index) => (
    `${index + 1}\n${timestamp(start)} --> ${timestamp(end)}\n${text}\n`
  )).join('\n');
}

function continuousNarration() {
  return NARRATION_CUES.map(([, , text]) => text).join('');
}

function cueTimingPlan() {
  return {
    targetDurationSeconds: 60,
    safetyMarginSeconds: 0.1,
    voice: { name: 'Microsoft Kangkang', culture: 'zh-CN', gender: 'Male' },
    cues: NARRATION_CUES.map(([start, end, text], index) => ({ index: index + 1, start, end, text })),
  };
}

function markdownText() {
  const rows = NARRATION_CUES.map(([start, end, text], index) => (
    `| ${timestamp(start).replace(',', '.')}–${timestamp(end).replace(',', '.')} | ${VISUALS[index]} | ${text} |`
  ));
  return [
    '# 腕上节律：官方模拟器健康数据演示文字稿',
    '',
    '| 时间码 | 画面 | 旁白 |',
    '| --- | --- | --- |',
    ...rows,
    '',
    '## 连续旁白',
    '',
    continuousNarration(),
    '',
  ].join('\n');
}

function writeIfAbsentOrIdentical(filePath, content) {
  if (fs.existsSync(filePath)) {
    if (fs.readFileSync(filePath, 'utf8') !== content) {
      throw new Error(`Existing artifact has different content and will not be replaced: ${filePath}`);
    }
    return;
  }
  fs.writeFileSync(filePath, content, 'utf8');
}

function writeTextArtifacts(outputDirectory = OUTPUT_DIRECTORY) {
  fs.mkdirSync(outputDirectory, { recursive: true });
  const artifacts = {
    srtPath: path.join(outputDirectory, SRT_FILENAME),
    markdownPath: path.join(outputDirectory, MARKDOWN_FILENAME),
    narrationPath: path.join(outputDirectory, NARRATION_FILENAME),
    cuePlanPath: path.join(outputDirectory, CUE_PLAN_FILENAME),
  };
  const contents = {
    [artifacts.srtPath]: srtText(),
