function readPcmWavMetadata(wav) {
  if (!Buffer.isBuffer(wav) || wav.toString('ascii', 0, 4) !== 'RIFF' || wav.toString('ascii', 8, 12) !== 'WAVE') {
    throw new Error('Expected a RIFF/WAVE buffer');
  }
  const dataOffset = wav.indexOf(Buffer.from('data'));
  if (dataOffset < 0 || dataOffset + 8 > wav.length) throw new Error('WAV data chunk is missing');
  const byteRate = wav.readUInt32LE(28);
  const dataSize = wav.readUInt32LE(dataOffset + 4);
  if (!byteRate || dataOffset + 8 + dataSize > wav.length) throw new Error('WAV data chunk is invalid');
  return {
    audioFormat: wav.readUInt16LE(20),
    channels: wav.readUInt16LE(22),
    sampleRate: wav.readUInt32LE(24),
    byteRate,
    bitsPerSample: wav.readUInt16LE(34),
    dataSize,
    durationSeconds: dataSize / byteRate,
  };
}

function assembleCuePcmTimeline({ cues, sampleRate, channels, bitsPerSample, durationSeconds }) {
  const bytesPerFrame = channels * (bitsPerSample / 8);
  const byteRate = sampleRate * bytesPerFrame;
  const dataSize = durationSeconds * byteRate;
  if (!Number.isInteger(dataSize) || !Array.isArray(cues) || !byteRate) throw new Error('Invalid PCM timeline parameters');
  const wav = Buffer.alloc(44 + dataSize);
  wav.write('RIFF', 0, 'ascii');
  wav.writeUInt32LE(36 + dataSize, 4);
  wav.write('WAVEfmt ', 8, 'ascii');
  wav.writeUInt32LE(16, 16);
  wav.writeUInt16LE(1, 20);
  wav.writeUInt16LE(channels, 22);
  wav.writeUInt32LE(sampleRate, 24);
  wav.writeUInt32LE(byteRate, 28);
  wav.writeUInt16LE(bytesPerFrame, 32);
  wav.writeUInt16LE(bitsPerSample, 34);
  wav.write('data', 36, 'ascii');
  wav.writeUInt32LE(dataSize, 40);
  for (const cue of cues) {
    if (!Buffer.isBuffer(cue.pcm) || cue.pcm.length % bytesPerFrame) throw new Error('Cue PCM is invalid');
    const offset = cue.start * byteRate;
    const windowLength = (cue.end - cue.start) * byteRate;
    if (!Number.isInteger(offset) || !Number.isInteger(windowLength) || cue.pcm.length > windowLength || offset < 0 || offset + cue.pcm.length > dataSize) {
      throw new Error('Cue PCM does not fit its timeline window without trimming');
    }
    cue.pcm.copy(wav, 44 + offset);
  }
  return wav;
}

