  27:   const resolvedPath = path.resolve(filePath);
  28:   const relativePath = path.relative(OUTPUT_DIRECTORY, resolvedPath);
  29:   if (!relativePath || relativePath.startsWith('..') || path.isAbsolute(relativePath)) {
  30:     throw new Error(`Unsafe composition output path outside ${OUTPUT_DIRECTORY}: ${resolvedPath}`);
  31:   }
  32:   return resolvedPath;
  33: }
  34: 
  35: function resolveFrameDirectory(frameDirectory) {
  36:   const resolvedDirectory = path.resolve(frameDirectory);
  37:   const relativePath = path.relative(OUTPUT_DIRECTORY, resolvedDirectory);
  38:   if (!relativePath || relativePath.startsWith('..') || path.isAbsolute(relativePath)) {
  39:     throw new Error(`Unsafe raw frame directory outside ${OUTPUT_DIRECTORY}: ${resolvedDirectory}`);
  40:   }
  41:   return resolvedDirectory;
  42: }
  43: 
  44: function locateFfmpeg(ffmpegPath = FFMPEG_PATH) {
  45:   const resolvedPath = path.resolve(ffmpegPath);
  46:   if (!fs.existsSync(resolvedPath) || !fs.statSync(resolvedPath).isFile()) {
  47:     throw new Error(`Bundled FFmpeg is missing: ${resolvedPath}. Expected output/video/.deps/imageio_ffmpeg/binaries/ffmpeg-win-x86_64-v7.1.exe`);
  48:   }
  49:   return resolvedPath;
  50: }
  51: 
  52: function framePattern(frameDirectory) {
  53:   return path.join(resolveFrameDirectory(frameDirectory), 'frame-%04d.png');
  54: }
  55: 
  56: function trimFilterGraph(editSegments = media.EDIT_SEGMENTS) {
  57:   const trims = editSegments.map(([start, end], index) => (
  58:     `[0:v]trim=start=${start}:end=${end},setpts=PTS-STARTPTS[v${index}]`
  59:   ));
  60:   const inputLabels = editSegments.map((_, index) => `[v${index}]`).join('');
  61:   return [
  62:     ...trims,
  63:     `${inputLabels}concat=n=${editSegments.length}:v=1:a=0[cut]`,
  64:     '[cut]scale=932:932:flags=lanczos,setsar=1,format=yuv420p[video]',
  65:   ].join(';');
  66: }
  67: 
  68: function buildIntermediateArguments({ frameDirectory, intermediatePath, fps = FPS }) {
  69:   return [
  70:     '-hide_banner', '-loglevel', 'error', '-n',
  71:     '-framerate', String(fps), '-start_number', '1', '-i', framePattern(frameDirectory),
  72:     '-map', '0:v:0', '-an', '-c:v', 'ffv1', '-level', '3', '-g', '1', '-pix_fmt', 'rgb24',
  73:     resolveOutputPath(intermediatePath),
  74:   ];
  75: }
  76: 
  77: function buildMasterArguments({ intermediatePath, masterPath, editSegments = media.EDIT_SEGMENTS }) {
  78:   return [
  79:     '-hide_banner', '-loglevel', 'error', '-n',
  80:     '-i', path.resolve(intermediatePath),
  81:     '-filter_complex', trimFilterGraph(editSegments),
  82:     '-map', '[video]', '-an', '-c:v', 'libx264', '-pix_fmt', 'yuv420p', '-movflags', '+faststart',
  83:     resolveOutputPath(masterPath),
  84:   ];
  85: }
  86: 
  87: function buildFinalArguments({ masterPath, narrationPath, subtitlePath, finalPath }) {
  88:   return [
  89:     '-hide_banner', '-loglevel', 'error', '-n',
  90:     '-i', path.resolve(masterPath), '-i', path.resolve(narrationPath),
  91:     '-sub_charenc', 'UTF-8', '-i', path.resolve(subtitlePath),
  92:     '-filter_complex', '[1:a]apad=whole_dur=60,atrim=duration=60[audio]',
  93:     '-map', '0:v:0', '-map', '[audio]', '-map', '2:0',
  94:     '-c:v', 'copy', '-c:a', 'aac', '-c:s', 'mov_text',
  95:     '-metadata:s:s:0', 'language=zho', '-t', String(TARGET_DURATION_SECONDS), '-movflags', '+faststart',
  96:     resolveOutputPath(finalPath),
  97:   ];
  98: }
  99: 
 100: function validateNarrationWav(narrationPath) {
 101:   const resolvedPath = path.resolve(narrationPath);
 102:   if (!fs.existsSync(resolvedPath)) throw new Error(`Narration WAV is missing: ${resolvedPath}`);
 103:   const metadata = media.readPcmWavMetadata(fs.readFileSync(resolvedPath));
 104:   if (metadata.durationSeconds > TARGET_DURATION_SECONDS) {
 105:     throw new Error(`Narration WAV exceeds 60 seconds; regenerate the cue-aligned narration instead of trimming speech: ${resolvedPath}`);
 106:   }
 107:   return metadata;
 108: }
 109: 
 110: function loadCaptureManifest(manifestPath = CAPTURE_MANIFEST_PATH) {
 111:   const resolvedPath = path.resolve(manifestPath);
 112:   if (!fs.existsSync(resolvedPath)) throw new Error(`Capture manifest is missing: ${resolvedPath}`);
 113:   let manifest;
 114:   try {
 115:     manifest = JSON.parse(fs.readFileSync(resolvedPath, 'utf8'));
 116:   } catch (error) {
 117:     throw new Error(`Capture manifest is not valid JSON: ${resolvedPath} (${error.message})`);
 118:   }
 119:   if (!manifest || !manifest.frameDirectory || manifest.fps !== FPS || !Number.isInteger(manifest.frames)) {
 120:     throw new Error(`Capture manifest is missing the required frameDirectory, ${FPS} fps, or frame count: ${resolvedPath}`);
 121:   }
 122:   return { ...manifest, frameDirectory: resolveFrameDirectory(manifest.frameDirectory) };
 123: }
 124: 
 125: function validateFrameSequence(frameDirectory, frames) {
 126:   if (!fs.existsSync(frameDirectory) || !fs.statSync(frameDirectory).isDirectory()) {
 127:     throw new Error(`Raw frame directory is missing: ${frameDirectory}`);
 128:   }
 129:   for (let index = 1; index <= frames; index += 1) {
 130:     const framePath = path.join(frameDirectory, `frame-${String(index).padStart(4, '0')}.png`);
 131:     if (!fs.existsSync(framePath) || !fs.statSync(framePath).size) {
 132:       throw new Error(`Missing or empty captured frame ${index}: ${framePath}`);
 133:     }
 134:   }
 135: }
 136: 
 137: function runFfmpeg(ffmpegPath, argumentsList, spawnSync = childProcess.spawnSync) {
 138:   const result = spawnSync(ffmpegPath, argumentsList, { encoding: 'utf8', shell: false });
 139:   if (result.error) throw new Error(`FFmpeg could not start: ${result.error.message}`);
 140:   if (result.status !== 0) {
 141:     const details = [result.stderr, result.stdout].filter(Boolean).join('\n').trim();
 142:     throw new Error(`FFmpeg failed with exit status ${result.status}${details ? `: ${details}` : ''}`);
 143:   }
 144:   return result;
 145: }
 146: 
 147: function assertAbsent(filePath, label) {
 148:   if (fs.existsSync(filePath)) throw new Error(`${label} already exists and will not be overwritten: ${filePath}`);
 149: }
 150: 
 151: function compose(options = {}) {
 152:   const manifest = loadCaptureManifest(options.manifestPath);
 153:   const frameDirectory = manifest.frameDirectory;
 154:   validateFrameSequence(frameDirectory, manifest.frames);
 155: 
 156:   const ffmpegPath = locateFfmpeg(options.ffmpegPath);
 157:   const masterPath = resolveOutputPath(options.masterPath || path.join(OUTPUT_DIRECTORY, MASTER_FILENAME));
 158:   const finalPath = resolveOutputPath(options.finalPath || path.join(OUTPUT_DIRECTORY, FINAL_FILENAME));
 159:   const narrationPath = path.resolve(options.narrationPath || path.join(OUTPUT_DIRECTORY, NARRATION_FILENAME));
 160:   const subtitlePath = path.resolve(options.subtitlePath || path.join(OUTPUT_DIRECTORY, SUBTITLE_FILENAME));
 161:   const intermediatePath = resolveOutputPath(options.intermediatePath || path.join(OUTPUT_DIRECTORY, `compose-intermediate-${process.pid}.mkv`));
 162: 
 163:   assertAbsent(masterPath, 'Silent master');
 164:   assertAbsent(finalPath, 'Final video');
 165:   assertAbsent(intermediatePath, 'Temporary intermediate');
 166:   validateNarrationWav(narrationPath);
 167:   if (!fs.existsSync(subtitlePath)) throw new Error(`UTF-8 SRT subtitle file is missing: ${subtitlePath}`);
 168: 
 169:   try {
 170:     runFfmpeg(ffmpegPath, buildIntermediateArguments({ frameDirectory, intermediatePath }), options.spawnSync);
 171:     runFfmpeg(ffmpegPath, buildMasterArguments({ intermediatePath, masterPath }), options.spawnSync);
 172:     runFfmpeg(ffmpegPath, buildFinalArguments({ masterPath, narrationPath, subtitlePath, finalPath }), options.spawnSync);
 173:   } finally {
 174:     if (fs.existsSync(intermediatePath)) fs.rmSync(intermediatePath);
 175:   }
 176:   return { masterPath, finalPath };
 177: }
 178: 
 179: if (require.main === module) {
 180:   try {
 181:     console.log(JSON.stringify(compose(), null, 2));
 182:   } catch (error) {
 183:     console.error(error.message || error);
 184:     process.exitCode = 1;
 185:   }
 186: }
 187: 
 188: module.exports = {
 189:   PROJECT_ROOT,
 190:   OUTPUT_DIRECTORY,
 191:   FFMPEG_PATH,
 192:   CAPTURE_MANIFEST_PATH,
 193:   MASTER_FILENAME,
 194:   FINAL_FILENAME,
 195:   FPS,
 196:   TARGET_DURATION_SECONDS,
 197:   resolveOutputPath,
 198:   resolveFrameDirectory,
 199:   locateFfmpeg,
 200:   framePattern,
 201:   trimFilterGraph,
 202:   buildIntermediateArguments,
 203:   buildMasterArguments,
 204:   buildFinalArguments,
 205:   validateNarrationWav,
 206:   loadCaptureManifest,
 207:   validateFrameSequence,
 208:   runFfmpeg,
 209:   compose,
 210: };
